; RetroBit TH probe -- generated by gen.py
	org 0
	dc.l $00FFFE00, Start
	rept 62
	dc.l Exc
	endr
	org $100
	dc.b "SEGA MEGA DRIVE "
	dc.b "(C)PROB 2026.OCT"
	dc.b "RETROBIT TH PROBE                               "
	dc.b "RETROBIT TH PROBE                               "
	dc.b "GM 00000000-00"
	dc.w 0
	dc.b "J               "
	dc.l 0, RomEnd-1
	dc.l $FF0000, $FFFFFF
	dc.b "            "
	dc.b "            "
	dc.b "                                        "
	dc.b "JUE             "
Exc:	bra.s Exc
Start:
	move.w #$2700,sr
	move.b $A10001,d0
	andi.b #$0F,d0
	beq.s .notmss
	move.l #$53454741,$A14000	; 'SEGA' for TMSS
.notmss:
	lea $C00004,a1
	lea $C00000,a3
	lea VdpRegs(pc),a2
	moveq #(VdpRegsEnd-VdpRegs)/2-1,d1
.r:	move.w (a2)+,(a1)
	dbra d1,.r
	move.l #$40000000,(a1)	; clear VRAM
	move.w #$7FFF,d1
.c:	move.w #0,(a3)
	dbra d1,.c
	move.l #$C0000000,(a1)	; CRAM: black, white, green
	move.w #$0000,(a3)
	move.w #$0EEE,(a3)
	move.l #$40000010,(a1)	; VSRAM
	move.w #0,(a3)
	move.w #0,(a3)
	move.l #$40000000,(a1)	; font -> tiles 0..63 (ASCII 32..95)
	lea Font(pc),a2
	move.w #(FontEnd-Font)/4-1,d1
.f:	move.l (a2)+,(a3)
	dbra d1,.f
	move.w #$8144,(a1)		; display on
	move.b #$40,$A10009		; port 1: TH output
	move.b #$40,$A10003		; TH high
	lea $FF0000,a5
	move.w #512-1,d0
.z:	clr.b (a5)+
	dbra d0,.z
; static text
	moveq #0,d0
	moveq #0,d1
	lea Title(pc),a2
	bsr PrintStr
	moveq #0,d0
	moveq #1,d1
	lea Sub1(pc),a2
	bsr PrintStr
	moveq #0,d0
	moveq #2,d1
	lea Hdr(pc),a2
	bsr PrintStr
	moveq #0,d0
	moveq #14,d1
	lea Sub2(pc),a2
	bsr PrintStr
	moveq #0,d0
	moveq #15,d1
	lea Hdr(pc),a2
	bsr PrintStr
	moveq #0,d0
	moveq #26,d1
	lea Foot(pc),a2
	bsr PrintStr
	lea Labels(pc),a2
	moveq #0,d7
.lab:	moveq #0,d0
	move.w d7,d1
	addq.w #3,d1
	move.l a2,-(sp)
	bsr PrintStr
	move.l (sp)+,a2
	moveq #0,d0
	move.w d7,d1
	add.w #16,d1
	bsr PrintStr			; a2 now past the label
	addq.w #1,d7
	cmpi.w #10,d7
	bne.s .lab

MainLoop:
	moveq #15,d5			; 16 rounds per screen update
Round:
	lea $A10003,a0
	lea $FF0100,a6		; raw reads
; ---- delay 0 nops
	move.w #2400,d6
.idle0:	dbra d6,.idle0		; >2ms idle: pad's 6-button counter resets
	move.b (a0),(a6)+		; H1 (TH idle high)
	rept 4
	move.b #$00,(a0)

	move.b (a0),(a6)+
	move.b #$40,(a0)

	move.b (a0),(a6)+
	endr
