	lea $FF0100,a6		; count bit5==0
	lea $FF0000,a5
	move.w #90-1,d0
.p:	btst #5,(a6)+
	bne.s .np
	addq.b #1,(a5)
.np:	addq.l #1,a5
	dbra d0,.p
	dbra d5,Round
	bsr Display
	bra MainLoop

Display:
	lea $FF0000,a5
	lea $FF0100,a6
	moveq #0,d6
.row:	moveq #0,d7
.slot:	move.w d7,d0
	mulu #3,d0
	addq.w #4,d0
	move.w d6,d1
	addq.w #3,d1
	move.b (a5),d5
	clr.b (a5)+
	bsr PrintHex
	move.w d7,d0
	mulu #3,d0
	addq.w #4,d0
	move.w d6,d1
	add.w #16,d1
	move.b (a6)+,d5
	bsr PrintHex
	addq.w #1,d7
	cmpi.w #9,d7
	bne.s .slot
	addq.w #1,d6
	cmpi.w #10,d6
	bne.s .row
	rts

; d0=x d1=y -> VDP write address of plane A cell (clobbers d2,d3)
SetPos:	move.w d1,d2
	lsl.w #6,d2
	add.w d0,d2
	add.w d2,d2
	add.w #$C000,d2
	moveq #0,d3
	move.w d2,d3
	andi.w #$3FFF,d3
	swap d3
	rol.w #2,d2
	andi.w #3,d2
	move.w d2,d3
	ori.l #$40000000,d3
	move.l d3,$C00004
	rts
; a2 = zero-terminated string (advanced past the 0)
PrintStr:	bsr SetPos
.l:	moveq #0,d2
	move.b (a2)+,d2
	beq.s .e
	subi.w #32,d2
	move.w d2,$C00000
	bra.s .l
.e:	rts
; d5.b printed as 2 hex digits at d0,d1
PrintHex:	bsr SetPos
	lea HexChars(pc),a4
	moveq #0,d2
	move.b d5,d2
	lsr.b #4,d2
	move.b (a4,d2.w),d2
	subi.w #32,d2
	move.w d2,$C00000
	moveq #0,d2
	move.b d5,d2
	andi.b #$0F,d2
	move.b (a4,d2.w),d2
	subi.w #32,d2
	move.w d2,$C00000
	rts

VdpRegs:	dc.w $8004,$8104,$8230,$8334,$8407,$8578,$8600,$8700,$8800,$8900,$8A00,$8B00,$8C81,$8D3F,$8E00,$8F02,$9001,$9100,$9200
