Title:	dc.b "RETROBIT TH PROBE - PORT 1",0
Sub1:	dc.b "TIMES BIT5=0 (C/START) IN 16 ROUNDS",0
Sub2:	dc.b "RAW LAST READ (HEX)",0
Hdr:	dc.b "NOP H1 L1 H2 L2 H3 L3 H4 L4 H5",0
Foot:	dc.b "HOLD C, THEN START, THEN BOTH",0
